  //============EUCLIDS===============//
  public static class Pair {
    long x;
    long y;
    long gcd;

    public Pair(long x, long y, long gcd) {
      this.x = x;
      this.y = y;
      this.gcd = gcd;
    }
  }

  public static Pair euclids(long a, long b) {
    if (b == 0) {
      return new Pair(1, 0, a);
    }
    Pair dash = euclids(b, a % b);

    return new Pair(dash.y, dash.x - ((a / b) * dash.y), dash.gcd);
  }
}
